<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import { accountState,signIn,signUp,signOut,synchronize,importGuestProgress,resolveAccountConflict,changeAccountPassword,accountError } from '@/core/utils/cloud-account'
import { readProfileSnapshot,cloudMeta,readProfileSafetyBackups } from '@/core/utils/local-db'
import { getDefaultBaseState,getDefaultSettingState } from '@/core/stores'
import { loadJsLib } from '@/core/utils'
import { LIB_JS_URL } from '@/core/config/env'
import saveAs from 'file-saver'
const mode=ref<'login'|'register'>('login'),username=ref(''),password=ref(''),repeat=ref(''),invite=ref(''),busy=ref(false),message=ref(''),error=ref(false),showPasswordForm=ref(false),oldPassword=ref(''),newPassword=ref(''),repeatNew=ref(''),confirmVersion=ref<'local'|'remote'|''>(''),allowGuestImport=ref(false)
const statuses:Record<string,string>={guest:'访客模式 · 保存到此浏览器',local:'个人本机副本',synced:'云端已同步',pending:'本机已保存 · 等待同步',syncing:'正在同步学习记录…',offline:'当前离线 · 本机记录已保留',conflict:'两份进度需要你选择',expired:'登录已过期 · 本机记录已保留',error:'同步未完成 · 可以重试'}
const localSummary=ref(''),remoteSummary=computed(()=>summarize(accountState.conflict?.snapshot))
const safetyBackups=ref<Array<{at:string;snapshot:any}>>([])
function summarize(snapshot:any){try{const records=JSON.parse(snapshot?.records?.['type-dutch-dict']||'null')?.val;if(!records)return '暂无学习记录';const daily=JSON.parse(records.noteData?.__type_dutch_daily_v1__||'{}'),b1=JSON.parse(records.noteData?.__type_dutch_b1_practice_v1__||'{}');return `${Object.keys(daily.days||{}).length} 个学习日有记录 · ${Object.keys(records.fsrsData||{}).length} 张复习卡 · ${Object.keys(b1.drafts||{}).length} 篇写作草稿`}catch{return '含有已保存的学习记录'}}
function when(value:string|number){return value?new Date(value).toLocaleString('zh-CN'):'尚未保存到云端'}
async function run(action:()=>Promise<any>){if(busy.value)return;busy.value=true;message.value='';error.value=false;try{await action()}catch(e){error.value=true;message.value=accountError(e)}finally{busy.value=false}}
async function submit(){await run(async()=>{if(mode.value==='register'){if(password.value!==repeat.value)throw Error('两次密码不一致。');await signUp(username.value,password.value,invite.value)}else await signIn(username.value,password.value)})}
async function retry(){await run(async()=>{await synchronize();if(accountState.status==='synced')message.value='学习记录已经同步。'})}
async function updatePassword(){await run(async()=>{if(newPassword.value!==repeatNew.value)throw Error('两次新密码不一致。');await changeAccountPassword(oldPassword.value,newPassword.value);oldPassword.value='';newPassword.value='';repeatNew.value='';showPasswordForm.value=false;message.value='密码已更新，其他设备需要重新登录。'})}
async function exportSafetyBackup(item:{at:string;snapshot:any}){await run(async()=>{
 const record=(key:string,fallback:any)=>item.snapshot.records[key]?JSON.parse(item.snapshot.records[key]):fallback
 const data={version:5,val:{dict:record('type-dutch-dict',{version:4,val:getDefaultBaseState()}),setting:record('type-dutch-setting',{version:23,val:getDefaultSettingState()}),TypeDutchPracticeWord:record('TypeDutchPracticeWord',{version:2,val:{}}),TypeDutchPracticeArticle:record('TypeDutchPracticeArticle',{version:1,val:{}})}}
 const JSZip=await loadJsLib('JSZip',LIB_JS_URL.JSZIP),zip=new JSZip();zip.file('data.json',JSON.stringify(data));saveAs(await zip.generateAsync({type:'blob'}),'Type-Dutch-Safety-'+item.at.replace(/[:.]/g,'-')+'.zip');message.value='副本已导出，可在设置中导入恢复（不包含自建音频文件）。'
})}
watch(()=>[accountState.ready,accountState.revision,accountState.conflict],async()=>{if(!accountState.ready)return;localSummary.value=summarize(await readProfileSnapshot());safetyBackups.value=await readProfileSafetyBackups();const meta=await cloudMeta();allowGuestImport.value=accountState.revision===0&&!meta.dirty},{immediate:true})
useSeoMeta({title:'Type Dutch · 账号与学习同步',description:'每人独立的学习记录，在不同电脑继续荷兰语学习。',robots:'noindex, nofollow'})
</script>
<template>
 <main class="account-page"><div class="account-wrap">
  <header><NuxtLink to="/plan">← 返回每日路线</NuxtLink><span>JE EIGEN LEERPAD</span></header>
  <section class="account-heading"><div class="eyebrow">个人账号 · 跨电脑继续</div><h1>换一台电脑，<br><em>接着自己的进度。</em></h1><p>每日路线、词汇复习、错词和写作笔记，跟着同一个账号走。</p></section>
  <p v-if="!accountState.ready" role="status">正在恢复登录和学习记录…</p>
  <div v-else class="account-grid">
   <section class="panel" v-if="!accountState.user||accountState.status==='expired'">
    <template v-if="!accountState.configured"><h2>账号同步还未启用</h2><p>管理员完成服务器连接后，这里就可以登录。现在仍可继续访客学习，原有记录保存在此浏览器。</p><NuxtLink class="primary link-button" to="/plan">继续本机学习 →</NuxtLink></template>
    <template v-else>
     <div class="form-tabs"><button type="button" :class="{selected:mode==='login'}" @click="mode='login'">登录账号</button><button type="button" v-if="accountState.registration!=='closed'" :class="{selected:mode==='register'}" @click="mode='register'">创建账号</button></div>
     <h2>{{ mode==='login'?'欢迎回来':'为自己留一个学习空间' }}</h2><p v-if="accountState.status==='expired'">重新登录后会保留此设备的离线进度。</p>
     <form @submit.prevent="submit">
      <label for="account-name">用户名</label><input id="account-name" v-model="username" autocomplete="username" autocapitalize="off" spellcheck="false" required minlength="3" maxlength="32" pattern="[a-zA-Z0-9][a-zA-Z0-9_.-]{2,31}" placeholder="例如 koala"/><small>3–32 位字母、数字、点、横线或下划线。</small>
      <label for="account-password">密码</label><input id="account-password" v-model="password" type="password" :autocomplete="mode==='login'?'current-password':'new-password'" required :minlength="mode==='register'?12:1" maxlength="256" :placeholder="mode==='register'?'至少 12 个字符，建议使用容易记住的长句':'输入你的密码'"/>
      <template v-if="mode==='register'"><label for="account-repeat">再次输入密码</label><input id="account-repeat" v-model="repeat" type="password" autocomplete="new-password" required minlength="12" maxlength="256"/><template v-if="accountState.registration==='invite'"><label for="account-invite">注册码</label><input id="account-invite" v-model="invite" type="password" autocomplete="off" required/><small>由网站管理员提供，用于控制新账号注册。</small></template></template>
      <button class="primary" type="submit" :disabled="busy">{{ busy?'正在处理…':mode==='login'?'登录并恢复进度 →':'创建我的账号 →' }}</button>
     </form><button v-if="accountState.status==='expired'" type="button" :disabled="busy" @click="run(()=>signOut(true))">退出当前账号，使用访客模式</button><p class="hint">此设备会保持登录。共享电脑使用完后，请在这里退出账号。忘记密码时请联系网站管理员。</p>
    </template>
   </section>
   <section class="panel" v-else>
    <span class="eyebrow">当前个人账号</span><h2 class="username">{{ accountState.user.username }}</h2><p class="status" :class="accountState.status">{{ accountState.status==='synced'&&!accountState.revision?'账号已连接 · 可以开始学习':statuses[accountState.status] }}</p><p class="small">最近云端保存：{{ when(accountState.lastSyncAt) }}</p><p class="small">{{ localSummary }}</p>
    <div class="buttons"><button class="primary" type="button" :disabled="busy||accountState.status==='syncing'||!!accountState.conflict" @click="retry">{{ accountState.status==='syncing'?'正在同步…':'立即同步' }}</button><NuxtLink class="link-button" to="/plan">继续学习 →</NuxtLink></div>
    <p v-if="accountState.message" class="service-message" role="status">{{ accountState.message }}</p>
    <section v-if="accountState.conflict" class="conflict-box"><h3>核对两份进度</h3><p>不会自动覆盖。选择前会保留本机副本；服务器也保留最近的保存版本。</p><div><b>此设备</b><p>{{ localSummary }}</p><small>上次同步：{{ when(accountState.lastSyncAt) }}</small></div><div><b>云端</b><p>{{ remoteSummary }}</p><small>保存时间：{{ when(accountState.conflict.updatedAt||'') }}</small></div><div class="buttons"><button type="button" @click="confirmVersion='remote'">选择云端版本</button><button type="button" @click="confirmVersion='local'">选择此设备版本</button></div><div v-if="confirmVersion" class="confirm-version"><p>{{ confirmVersion==='remote'?'将恢复云端进度，重新加载页面；此设备当前副本会保留。':'将用此设备的完整进度更新云端；云端旧版本会保留。' }}</p><button type="button" :disabled="busy" @click="run(()=>resolveAccountConflict(confirmVersion as 'local'|'remote'))">确认使用{{ confirmVersion==='remote'?'云端':'此设备' }}版本</button><button type="button" @click="confirmVersion=''">取消</button></div></section>
    <section v-if="accountState.guestAvailable&&allowGuestImport" class="import-box"><h3>带上这台电脑原来的学习记录</h3><p>首次使用空账号时，可以复制此浏览器的访客进度。原访客记录仍会保留。</p><button type="button" :disabled="busy" @click="run(importGuestProgress)">导入原有访客记录并同步</button></section>
    <details v-if="safetyBackups.length" class="safety-backups"><summary>同步安全副本 · {{ safetyBackups.length }} 份</summary><p>这里保留拉取云端或选择进度前的本机副本。可导出后到设置中恢复，不包含自建音频文件。</p><div v-for="item in safetyBackups" :key="item.at"><small>{{ when(item.at) }} · {{ summarize(item.snapshot) }}</small><button type="button" :disabled="busy" @click="exportSafetyBackup(item)">导出此副本</button></div></details>
    <div class="account-tools"><button type="button" @click="showPasswordForm=!showPasswordForm">修改密码</button><button type="button" :disabled="busy" @click="run(()=>signOut())">同步并退出账号</button><button v-if="['offline','error','expired','conflict'].includes(accountState.status)" type="button" :disabled="busy" @click="run(()=>signOut(true))">保留本机副本并退出</button></div>
    <form v-if="showPasswordForm" class="password-form" @submit.prevent="updatePassword"><label for="old-password">当前密码</label><input id="old-password" v-model="oldPassword" type="password" autocomplete="current-password" required/><label for="new-password">新密码（至少 12 个字符）</label><input id="new-password" v-model="newPassword" type="password" autocomplete="new-password" required minlength="12" maxlength="256"/><label for="repeat-password">再次输入新密码</label><input id="repeat-password" v-model="repeatNew" type="password" autocomplete="new-password" required minlength="12" maxlength="256"/><button type="submit" :disabled="busy">更新密码</button></form>
   </section>
   <aside class="panel explanation"><h2>同一个人，同一份进度</h2><ol><li><b>第一次使用</b><p>创建个人账号；已有本机记录可在空账号里导入。</p></li><li><b>在另一台电脑</b><p>打开同一个网站，登录同一个账号，恢复自己的学习路线。</p></li><li><b>多人使用</b><p>每人创建不同账号。退出后切回独立的访客记录，其他人再登录自己的账号。</p></li></ol><p>网络中断时会先保存到当前设备；恢复网络后再同步。离开电脑前可点击“立即同步”确认。</p><NuxtLink to="/setting?index=5">导出 / 导入完整学习备份 ↗</NuxtLink></aside>
  </div>
  <p v-if="message" role="status" class="result" :class="{error}">{{ message }}</p>
  <p v-if="!accountState.user&&accountState.message" class="result error" role="status">{{ accountState.message }}</p>
  <footer>账号用于同步你的学习记录。发音和课程内容保持原样；每个人都有独立的学习空间。</footer>
 </div></main>
</template>
<style scoped>
.account-page{height:100%;overflow:auto;background:#fafaf4;color:#2b4235;font:14px/1.8 'Segoe UI','Microsoft YaHei',sans-serif}.account-wrap{max-width:1100px;margin:auto;padding:25px 36px 55px;box-sizing:border-box}*{box-sizing:border-box}header{display:flex;justify-content:space-between;border-bottom:1px solid #dfe5d5;padding-bottom:18px;font-size:11px;color:#667b5d}header>span,.eyebrow{font-size:10px;letter-spacing:1.5px;color:#768763}.account-heading{padding:35px 0 25px}h1{font-size:clamp(30px,3.5vw,42px);line-height:1.5;letter-spacing:-1px;margin:12px 0}h1 em{font-style:normal;color:#b8522c}.account-heading p{font-size:13px;color:#63775a}a{color:inherit;text-decoration:none}.account-grid{display:grid;grid-template-columns:1.25fr 1fr;gap:22px;align-items:start}.panel{border:1px solid #dce4d1;border-radius:13px;background:#fffef9;padding:26px}h2{font-size:21px;line-height:1.6;margin:6px 0 15px}h3{font-size:15px;margin:0 0 10px}.panel p{font-size:12px;color:#62745a}.form-tabs{display:flex;border-bottom:1px solid #e0e7d5;gap:20px;margin-bottom:22px}.form-tabs button{border:0;border-bottom:2px solid transparent;border-radius:0;padding:7px 0 12px;background:transparent}.form-tabs .selected{border-color:#b6502c;color:#a14b2d}label{display:block;font-size:12px;margin:17px 0 7px}input{width:100%;min-width:0;border:1px solid #c1d0b1;border-radius:7px;padding:11px 12px;color:#294230;background:white;font:inherit;font-size:13px}small{display:block;font-size:10px;color:#778566;margin-top:6px}button,.link-button{font:inherit;font-size:12px;border:1px solid #ccdbbf;border-radius:7px;background:#f2f6e9;color:#4c6b3d;padding:10px 15px;cursor:pointer}button:disabled{opacity:.55;cursor:default}.primary{background:#bb512b;border-color:#bb512b;color:white}form>.primary{width:100%;margin-top:23px}.hint{font-size:10px!important;color:#7a846e!important;margin-top:20px}.buttons{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:19px 0}.small{font-size:11px!important}.status{padding:12px 15px;border-radius:7px;background:#eff4e5;color:#547840!important}.status.offline,.status.conflict,.status.error,.status.expired{background:#fff0df;color:#97552f!important}.username{font:32px/1.4 Georgia,serif;margin-top:12px;overflow-wrap:anywhere}.service-message{padding:12px;border:1px solid #dec6ab;border-radius:7px;background:#fff6e9}.account-tools{display:flex;gap:14px;flex-wrap:wrap;border-top:1px solid #e1e7d6;margin-top:25px;padding-top:17px}.account-tools button{border:0;border-radius:0;background:transparent;padding:5px 0;font-size:10px;text-decoration:underline;text-underline-offset:4px}.conflict-box,.import-box{border:1px solid #d7c5a5;background:#fff7e8;border-radius:9px;padding:18px;margin:22px 0}.import-box{border-color:#d4dfc5;background:#f1f6e7}.conflict-box>div:not(.buttons):not(.confirm-version){border-top:1px solid #e6d9c2;padding:11px 0;font-size:12px}.conflict-box b{font-size:12px}.conflict-box p{margin:7px 0}.confirm-version{border:1px solid #dcc5a8;border-radius:7px;padding:12px}.confirm-version button{font-size:10px;margin:7px 8px 0 0}.password-form{border-top:1px solid #e1e7d6;margin-top:15px;padding-top:3px}.password-form button{margin-top:17px}.explanation{background:#f0f5e7}.explanation h2{font-size:19px}.explanation ol{padding-left:21px;margin:25px 0}.explanation li{padding:0 0 17px 7px;font-size:12px}.explanation li p{margin:5px 0;color:#68795f}.explanation>a{font-size:11px;color:#9a5e38;text-decoration:underline}.result{padding:14px 17px;border:1px solid #d3dfc5;border-radius:8px;background:#edf5e4;font-size:12px}.result.error{border-color:#dec2a6;background:#fff2e4;color:#a15231}footer{font-size:11px;color:#78846c;border-top:1px solid #e1e7d7;margin-top:30px;padding-top:18px}input:focus-visible,button:focus-visible,a:focus-visible{outline:2px solid #bd542d;outline-offset:3px}@media(max-width:750px){.account-wrap{padding:20px 17px 40px}.account-grid{grid-template-columns:1fr}.panel{padding:21px}.account-heading{padding-top:26px}header>span{display:none}}
.safety-backups{font-size:11px;margin-top:20px;border-top:1px solid #dfe7d2;padding-top:15px}.safety-backups summary{cursor:pointer;color:#5e784b}.safety-backups>div{display:flex;gap:12px;align-items:center;justify-content:space-between;border-top:1px solid #e1e7d6;padding:12px 0}.safety-backups button{font-size:10px;white-space:nowrap}
